<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { request, query, type Page } from '../api'
import { dateTime } from '../domain.js'
import StatusBadge from './StatusBadge.vue'
import Modal from './Modal.vue'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),current=ref<any>(null),notes=ref('')
const names:Record<string,string>={badge:'徽章',growth:'成长值',coupon:'优惠券',maintenance_coupon:'维修养护券',physical_gift:'实物礼包',event_invitation:'活动邀请资格'}
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/admin/course-rewards'+query({page:page.value,page_size:10}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function fulfill(){if(!current.value||saving.value)return;saving.value=true;error.value='';try{await request(`/admin/course-rewards/${current.value.id}/fulfill`,{method:'POST',body:JSON.stringify({notes:notes.value})});current.value=null;success.value='实物交付记录已保存';await load()}catch(err){error.value=(err as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><h1>课程奖励发放</h1><p>查看课程奖励领取记录。实物礼包交付后填写发放凭据，活动邀请资格仍需用户主动报名。</p></div><button class="button" @click="load">刷新记录</button></div>
  <p v-if="error&&!current" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p>
  <section class="panel"><div class="filter-bar"><span class="record-count">共 {{ total }} 条奖励记录</span></div><div class="table-scroll"><table><thead><tr><th>编号</th><th>用户</th><th>奖励名称</th><th>类型 / 权益</th><th>状态</th><th>发放记录</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无课程奖励领取记录</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td>#{{ row.user_id }}</td><td class="cell-title">{{ row.reward_snapshot?.title||'课程奖励' }}</td><td>{{ names[row.reward_snapshot?.reward_type]||row.reward_snapshot?.reward_type }}<small v-if="row.reward_snapshot?.points" class="muted"> · {{ row.reward_snapshot.points }} 成长值</small><small v-if="row.reward_snapshot?.coupon_id" class="muted"> · 券 #{{ row.reward_snapshot.coupon_id }}</small><small v-if="row.reward_snapshot?.event_id" class="muted"> · 活动 #{{ row.reward_snapshot.event_id }}</small></td><td><StatusBadge :value="row.status" /></td><td>{{ row.notes||'—' }}<small class="muted">{{ dateTime(row.updated_at) }}</small></td><td><button v-if="row.status==='pending_fulfillment'&&row.reward_snapshot?.reward_type==='physical_gift'" class="text-button" @click="current=row;notes='';error=''">登记实物交付</button><span v-else class="muted">—</span></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
  <Modal v-if="current" title="登记实物交付" @close="!saving&&(current=null)"><form id="reward-fulfill" @submit.prevent="fulfill"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><p class="notice">{{ current.reward_snapshot?.title }} · 用户 #{{ current.user_id }}</p><label><span>交付凭据与说明 *</span><textarea v-model="notes" rows="4" required maxlength="2000" placeholder="填写配送单号、收件确认或现场领取凭据" /></label></form><template #footer><button class="button" :disabled="saving" @click="current=null">取消</button><button class="button primary" :disabled="saving" form="reward-fulfill">{{ saving?'正在提交…':'确认已交付' }}</button></template></Modal>
</template>
